import { describe, expect, it } from "vitest";

import { assertDealTransitionAllowed } from "@/domain/dealRegistration";

describe("assertDealTransitionAllowed", () => {
  it("blocks an invalid jump from draft straight to approved", () => {
    // Why this test matters: workflow shortcuts are one of the fastest ways to corrupt enterprise approval data.
    // Production bug caught by this test: a refactor that accidentally lets clients skip sales and channel review.
    expect(() =>
      assertDealTransitionAllowed(
        {
          userId: "demo-channel-manager",
          email: "channel-manager@example.com",
          displayName: "Casey Channel",
          role: "CHANNEL_MANAGER",
          partnerOrgId: null,
        },
        "DRAFT",
        "APPROVED",
      ),
    ).toThrow("Cannot move a deal from DRAFT to APPROVED.");
  });
});

/**
 * What this file does: defines the centralized RBAC matrix and the helpers that enforce it.
 * What calls it: routes, services, and domain state machines across src/services and src/domain.
 * What it calls: src/lib/errors.ts for permission failures.
 * One thing a junior engineer would likely get wrong when writing something similar: sprinkling ad hoc `session.role === ...` checks around the codebase until authorization becomes impossible to audit.
 */
import { ForbiddenError } from "@/lib/errors";
import type { RequestSession, UserRole } from "@/types/auth";

export const permissions = [
  "partner:read",
  "partner:manage",
  "deal:read",
  "deal:create",
  "deal:submit",
  "deal:approve_sales",
  "deal:approve_channel",
  "deal:close",
  "mdf:read",
  "mdf:create",
  "mdf:decide",
  "mdf:reimburse",
  "certification:manage",
  "reports:view",
  "jobs:process",
] as const;

