// reduced to the permissions the deal flow uses, and the error classes of src/lib/errors.ts:3-36.
export class AppError extends Error {
  constructor(message, statusCode, code) {
    super(message);
    this.statusCode = statusCode;
    this.code = code;
  }
}

export class ForbiddenError extends AppError {
  constructor(message = "You do not have permission to perform this action.") {
    super(message, 403, "FORBIDDEN");
  }
}

export class ConflictError extends AppError {
  constructor(message) {
    super(message, 409, "CONFLICT");
  }
}

const rolePermissionMatrix = {
  PLATFORM_ADMIN: ["deal:read", "deal:create", "deal:submit", "deal:approve_sales", "deal:approve_channel", "deal:close", "jobs:process"],
  CHANNEL_MANAGER: ["deal:read", "deal:create", "deal:approve_channel", "deal:close"],
  SALES_REP: ["deal:read", "deal:create", "deal:approve_sales", "deal:close"],
  FINANCE_MANAGER: ["deal:read", "jobs:process"],
  PARTNER_ADMIN: ["deal:read", "deal:create", "deal:submit"],
  PARTNER_SELLER: ["deal:read", "deal:create", "deal:submit"],
};

export function hasPermission(session, permission) {
  return rolePermissionMatrix[session.role].includes(permission);
}

export function assertPermission(session, permission) {
  if (!hasPermission(session, permission)) {
    throw new ForbiddenError(`Role ${session.role} cannot perform ${permission}.`);
  }
}

const allowedTransitions = {
  DRAFT: ["SUBMITTED"],
  SUBMITTED: ["SALES_APPROVED", "REJECTED"],
  SALES_APPROVED: ["APPROVED", "REJECTED"],
  APPROVED: ["CLOSED_WON", "CLOSED_LOST"],
  REJECTED: [],
  CLOSED_WON: [],
  CLOSED_LOST: [],
};

export function assertDealTransitionAllowed(session, currentStatus, nextStatus) {
  if (!allowedTransitions[currentStatus].includes(nextStatus)) {
    throw new ConflictError(`Cannot move a deal from ${currentStatus} to ${nextStatus}.`);
  }

  if (nextStatus === "SUBMITTED") {
    assertPermission(session, "deal:submit");
    return;
  }

  if (nextStatus === "SALES_APPROVED") {
    assertPermission(session, "deal:approve_sales");
    return;
  }

  if (nextStatus === "APPROVED") {
    assertPermission(session, "deal:approve_channel");
    return;
  }

  if (nextStatus === "REJECTED") {
    const permission = currentStatus === "SUBMITTED" ? "deal:approve_sales" : "deal:approve_channel";
    assertPermission(session, permission);
    return;
  }

  // ⚠️ SENIOR NOTE: Close outcomes look simple, but if the same permission later controls forecasting exports, it becomes revenue-sensitive quickly.
  assertPermission(session, "deal:close");
}

